insert into backgrounds (id, name, description, equipment, coins_copper, material, extra_languages, known_settings, sort) values
($q$acolyte$q$, $q$Acolyte |cs| Akolyta$q$, $q$You served in a temple of the Star God: lighting candles, copying prayers, listening to confessions. |cs| Sloužil jsi v chrámu Hvězdného boha: zapaloval svíce, opisoval modlitby, poslouchal zpovědi.$q$, $q$[{"options": [{"entries": [{"items": ["quarterstaff", "mace", "club"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["holy-symbol"], "quantity": 1}, {"items": ["prayer-book"], "quantity": 1}, {"items": ["vestments"], "quantity": 1}, {"items": ["quill"], "quantity": 1}, {"items": ["ink"], "quantity": 1}, {"items": ["parchment"], "quantity": 5}]}]}]$q$::jsonb, 150, 3, 1, $q$Temples and monasteries; the clergy and the faithful. |cs| Chrámy a kláštery; duchovenstvo a věřící.$q$, 1),
($q$artisan$q$, $q$Artisan |cs| Řemeslník$q$, $q$You learned a trade in a master's workshop and carry your tools and your guild's letter wherever you go. |cs| Vyučil ses řemeslu v mistrově dílně a nástroje i cechovní list nosíš všude s sebou.$q$, $q$[{"options": [{"entries": [{"items": ["smiths-hammer"], "quantity": 1}, {"items": ["tongs"], "quantity": 1}, {"items": ["file"], "quantity": 1}]}, {"entries": [{"items": ["saw"], "quantity": 1}, {"items": ["plane"], "quantity": 1}, {"items": ["chisels"], "quantity": 1}, {"items": ["auger"], "quantity": 1}, {"items": ["claw-hammer"], "quantity": 1}]}, {"entries": [{"items": ["leather-knife"], "quantity": 1}, {"items": ["awl"], "quantity": 1}, {"items": ["needle-and-thread"], "quantity": 1}, {"items": ["last"], "quantity": 1}]}, {"entries": [{"items": ["carding-combs"], "quantity": 1}, {"items": ["drop-spindle"], "quantity": 1}, {"items": ["hand-loom"], "quantity": 1}]}, {"entries": [{"items": ["brewing-kettle"], "quantity": 1}, {"items": ["mash-paddle"], "quantity": 1}, {"items": ["sieve"], "quantity": 1}, {"items": ["ladle"], "quantity": 1}]}, {"entries": [{"items": ["masons-hammer"], "quantity": 1}, {"items": ["chisels"], "quantity": 1}, {"items": ["trowel"], "quantity": 1}, {"items": ["masons-square"], "quantity": 1}]}, {"entries": [{"items": ["potters-ribs"], "quantity": 1}, {"items": ["potters-wire"], "quantity": 1}]}, {"entries": [{"items": ["jewellers-files"], "quantity": 1}, {"items": ["jewellers-saw"], "quantity": 1}, {"items": ["tweezers"], "quantity": 1}, {"items": ["touchstone"], "quantity": 1}]}, {"entries": [{"items": ["kitchen-knives"], "quantity": 1}, {"items": ["iron-pot"], "quantity": 1}, {"items": ["ladle"], "quantity": 1}, {"items": ["spice-box"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["light-hammer", "handaxe", "dagger"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["guild-letter"], "quantity": 1}, {"items": ["pouch"], "quantity": 2}, {"items": ["travellers-clothes"], "quantity": 1}]}]}]$q$::jsonb, 500, 5, 0, $q$Workshops and guilds; craftspeople and their customers. |cs| Dílny a cechy; řemeslníci a jejich zákazníci.$q$, 2),
($q$charlatan$q$, $q$Charlatan |cs| Šarlatán$q$, $q$You sold miracle cures, false relics and noble titles that never existed. Some towns still want a word with you. |cs| Prodával jsi zázračné léky, falešné ostatky a šlechtické tituly, které nikdy neexistovaly. Některá města s tebou ještě chtějí mluvit.$q$, $q$[{"options": [{"entries": [{"items": ["cosmetics"], "quantity": 1}, {"items": ["hair-dye"], "quantity": 1}, {"items": ["false-beard"], "quantity": 1}, {"items": ["small-mirror"], "quantity": 1}]}, {"entries": [{"items": ["blank-seals"], "quantity": 1}, {"items": ["wax-tools"], "quantity": 1}, {"items": ["sealing-wax"], "quantity": 1}, {"items": ["quill"], "quantity": 1}, {"items": ["ink"], "quantity": 1}, {"items": ["parchment"], "quantity": 5}]}]}, {"options": [{"entries": [{"items": ["coloured-bottles", "weighted-dice", "marked-cards", "fake-signet"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["dagger"], "quantity": 1}, {"items": ["fine-clothes"], "quantity": 1}]}]}]$q$::jsonb, 200, 1, 1, $q$Markets and fairs; marks, swindlers and the gullible. |cs| Trhy a jarmarky; oběti, podvodníci a důvěřiví.$q$, 3),
($q$criminal$q$, $q$Criminal |cs| Zločinec$q$, $q$You made your living outside the law: picking locks, picking pockets, or breaking heads for someone who paid. |cs| Živil ses mimo zákon: otvíral zámky, kapsy, nebo rozbíjel hlavy pro toho, kdo zaplatil.$q$, $q$[{"options": [{"entries": [{"items": ["dagger"], "quantity": 2}]}, {"entries": [{"items": ["dagger"], "quantity": 1}, {"items": ["club"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["leather-jerkin"], "quantity": 1}, {"items": ["crowbar"], "quantity": 1}, {"items": ["file"], "quantity": 1}, {"items": ["lockpicks"], "quantity": 1}, {"items": ["small-mirror"], "quantity": 1}, {"items": ["scissors"], "quantity": 1}, {"items": ["pliers"], "quantity": 1}, {"items": ["dark-hooded-clothes"], "quantity": 1}, {"items": ["pouch"], "quantity": 2}]}]}]$q$::jsonb, 300, 1, 1, $q$The underworld; thieves, fences and gangs. |cs| Podsvětí; zloději, překupníci a gangy.$q$, 4),
($q$farmer$q$, $q$Farmer |cs| Sedlák$q$, $q$You worked the land from dawn to dusk. You know weather, livestock and how to mend a fence with what's lying around. |cs| Od úsvitu do soumraku jsi dřel na poli. Rozumíš počasí, dobytku a tomu, jak spravit plot tím, co se válí kolem.$q$, $q$[{"options": [{"entries": [{"items": ["spear", "quarterstaff", "flail"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["sickle"], "quantity": 1}, {"items": ["saw"], "quantity": 1}, {"items": ["plane"], "quantity": 1}, {"items": ["chisels"], "quantity": 1}, {"items": ["auger"], "quantity": 1}, {"items": ["claw-hammer"], "quantity": 1}, {"items": ["splints"], "quantity": 1}, {"items": ["needle-and-thread"], "quantity": 1}, {"items": ["iron-pot"], "quantity": 1}, {"items": ["shovel"], "quantity": 1}, {"items": ["common-clothes"], "quantity": 1}]}]}]$q$::jsonb, 300, 6, 0, $q$Villages and farmland; peasants, millers and bailiffs. |cs| Vesnice a pole; sedláci, mlynáři a dráby.$q$, 5),
($q$folk-hero$q$, $q$Folk hero |cs| Lidový hrdina$q$, $q$You stood up to a tyrant, a beast or a flood, and the common folk still tell the story, usually bigger than it was. |cs| Postavil ses tyranovi, bestii nebo povodni a prostí lidé ten příběh pořád vyprávějí, obvykle větší, než byl.$q$, $q$[{"options": [{"entries": [{"items": ["smiths-hammer"], "quantity": 1}, {"items": ["tongs"], "quantity": 1}, {"items": ["file"], "quantity": 1}]}, {"entries": [{"items": ["saw"], "quantity": 1}, {"items": ["plane"], "quantity": 1}, {"items": ["chisels"], "quantity": 1}, {"items": ["auger"], "quantity": 1}, {"items": ["claw-hammer"], "quantity": 1}]}, {"entries": [{"items": ["leather-knife"], "quantity": 1}, {"items": ["awl"], "quantity": 1}, {"items": ["needle-and-thread"], "quantity": 1}, {"items": ["last"], "quantity": 1}]}, {"entries": [{"items": ["carding-combs"], "quantity": 1}, {"items": ["drop-spindle"], "quantity": 1}, {"items": ["hand-loom"], "quantity": 1}]}, {"entries": [{"items": ["brewing-kettle"], "quantity": 1}, {"items": ["mash-paddle"], "quantity": 1}, {"items": ["sieve"], "quantity": 1}, {"items": ["ladle"], "quantity": 1}]}, {"entries": [{"items": ["masons-hammer"], "quantity": 1}, {"items": ["chisels"], "quantity": 1}, {"items": ["trowel"], "quantity": 1}, {"items": ["masons-square"], "quantity": 1}]}, {"entries": [{"items": ["potters-ribs"], "quantity": 1}, {"items": ["potters-wire"], "quantity": 1}]}, {"entries": [{"items": ["jewellers-files"], "quantity": 1}, {"items": ["jewellers-saw"], "quantity": 1}, {"items": ["tweezers"], "quantity": 1}, {"items": ["touchstone"], "quantity": 1}]}, {"entries": [{"items": ["kitchen-knives"], "quantity": 1}, {"items": ["iron-pot"], "quantity": 1}, {"items": ["ladle"], "quantity": 1}, {"items": ["spice-box"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["spear", "handaxe", "quarterstaff", "flail"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["gambeson"], "quantity": 1}, {"items": ["shovel"], "quantity": 1}, {"items": ["iron-pot"], "quantity": 1}, {"items": ["common-clothes"], "quantity": 1}]}]}]$q$::jsonb, 300, 2, 0, $q$Villages and the common folk who know your deed. |cs| Vesnice a prostý lid, který zná tvůj čin.$q$, 6),
($q$guard$q$, $q$Guard |cs| Strážný$q$, $q$You stood on a town wall or at a lord's gate, checking carts, breaking up brawls and pretending not to see the bribes. |cs| Stával jsi na hradbách nebo u pánovy brány, kontroloval vozy, rozháněl rvačky a dělal, že nevidíš úplatky.$q$, $q$[{"options": [{"entries": [{"items": ["spear"], "quantity": 1}, {"items": ["light-crossbow"], "quantity": 1}, {"items": ["bolts"], "quantity": 1}, {"items": ["quiver"], "quantity": 1}]}, {"entries": [{"items": ["spear"], "quantity": 1}, {"items": ["shield", "heater-shield", "kite-shield"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["gambeson"], "quantity": 1}, {"items": ["iron-cap"], "quantity": 1}, {"items": ["hooded-lantern"], "quantity": 1}, {"items": ["manacles"], "quantity": 1}, {"items": ["common-clothes"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["dice-set", "playing-cards"], "quantity": 1}]}]}]$q$::jsonb, 300, 1, 0, $q$Town watches and gatehouses; the law and its enforcers. |cs| Městské hlídky a brány; zákon a ti, kdo ho vymáhají.$q$, 7),
($q$guide$q$, $q$Guide |cs| Průvodce$q$, $q$You led merchants, pilgrims and lost lordlings through forests and mountain passes, for a fee. |cs| Za úplatu jsi vodil kupce, poutníky a ztracené šlechtice lesy a horskými průsmyky.$q$, $q$[{"options": [{"entries": [{"items": ["shortbow"], "quantity": 1}, {"items": ["arrows"], "quantity": 1}, {"items": ["quiver"], "quantity": 1}]}, {"entries": [{"items": ["sling"], "quantity": 1}, {"items": ["sling-bullets"], "quantity": 1}, {"items": ["spear", "handaxe"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["hide-jerkin"], "quantity": 1}, {"items": ["drawing-compasses"], "quantity": 1}, {"items": ["ruler"], "quantity": 1}, {"items": ["quill"], "quantity": 1}, {"items": ["ink"], "quantity": 1}, {"items": ["parchment"], "quantity": 5}, {"items": ["tent"], "quantity": 1}, {"items": ["bedroll"], "quantity": 1}, {"items": ["travellers-clothes"], "quantity": 1}]}]}]$q$::jsonb, 250, 2, 1, $q$Roads, trails and the wild borderlands; travellers who hire you. |cs| Cesty, stezky a divoké pohraničí; pocestní, kteří si tě najmou.$q$, 8),
($q$hermit$q$, $q$Hermit |cs| Poustevník$q$, $q$You lived alone for years, in a cave, a forest hut or a cell, looking for an answer. You may even have found one. |cs| Léta jsi žil sám, v jeskyni, lesní chatrči nebo cele, a hledal odpověď. Možná jsi ji i našel.$q$, $q$[{"options": [{"entries": [{"items": ["quarterstaff"], "quantity": 1}, {"items": ["leather-gloves"], "quantity": 1}, {"items": ["clippers"], "quantity": 1}, {"items": ["mortar-and-pestle"], "quantity": 1}, {"items": ["glass-jar"], "quantity": 3}, {"items": ["pouch"], "quantity": 2}, {"items": ["philosophy-book"], "quantity": 1}, {"items": ["scroll-case-of-notes"], "quantity": 1}, {"items": ["lamp"], "quantity": 1}, {"items": ["oil-flask"], "quantity": 3}, {"items": ["bedroll"], "quantity": 1}, {"items": ["winter-blanket"], "quantity": 1}, {"items": ["common-clothes"], "quantity": 1}]}]}]$q$::jsonb, 50, 6, 1, $q$Hermitages and holy wild places; recluses and pilgrims. |cs| Poustevny a posvátná divoká místa; samotáři a poutníci.$q$, 9),
($q$merchant$q$, $q$Merchant |cs| Obchodník$q$, $q$You bought cheap and sold dear, from a market stall or a wagon on the trade road. You know what everything is worth. |cs| Kupoval jsi levně a prodával draze, ze stánku na trhu nebo z vozu na obchodní cestě. Víš, co má jakou cenu.$q$, $q$[{"options": [{"entries": [{"items": ["dagger", "mace", "club"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["scales"], "quantity": 1}, {"items": ["counting-cloth"], "quantity": 1}, {"items": ["ledger"], "quantity": 1}, {"items": ["quill"], "quantity": 1}, {"items": ["ink"], "quantity": 1}, {"items": ["pouch"], "quantity": 2}, {"items": ["travellers-clothes"], "quantity": 1}]}]}]$q$::jsonb, 500, 3, 1, $q$Markets, guildhalls and trade roads; merchants and their clerks. |cs| Trhy, cechovní domy a obchodní cesty; kupci a jejich písaři.$q$, 10),
($q$noble$q$, $q$Noble |cs| Šlechtic$q$, $q$You were born to a family with a name, a coat of arms and debts. You were taught to ride, to dance and to give orders. |cs| Narodil ses do rodu se jménem, erbem a dluhy. Naučili tě jezdit, tančit a rozkazovat.$q$, $q$[{"options": [{"entries": [{"items": ["dagger", "spear", "mace", "longsword", "shortsword", "rapier"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["fine-clothes"], "quantity": 1}, {"items": ["signet-ring"], "quantity": 1}, {"items": ["scroll-of-pedigree"], "quantity": 1}, {"items": ["perfume"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["dice-set", "playing-cards"], "quantity": 1}]}]}]$q$::jsonb, 200, 0, 1, $q$Noble courts and castles; the nobility and their servants. |cs| Šlechtické dvory a hrady; šlechta a její služebnictvo.$q$, 11),
($q$outlander$q$, $q$Outlander |cs| Člověk z divočiny$q$, $q$You grew up far from towns, among hunters, herders or a wild clan. Walls make you nervous. |cs| Vyrostl jsi daleko od měst, mezi lovci, pastevci nebo divokým klanem. Z hradeb jsi nesvůj.$q$, $q$[{"options": [{"entries": [{"items": ["quarterstaff", "spear", "handaxe", "greatclub"], "quantity": 1}]}, {"entries": [{"items": ["shortbow"], "quantity": 1}, {"items": ["arrows"], "quantity": 1}, {"items": ["quiver"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["hide-jerkin"], "quantity": 1}, {"items": ["hunting-trap"], "quantity": 1}, {"items": ["animal-trophy"], "quantity": 1}, {"items": ["bedroll"], "quantity": 1}, {"items": ["travellers-clothes"], "quantity": 1}]}]}]$q$::jsonb, 300, 6, 1, $q$The wild and its clans; hunters, herders and trappers. |cs| Divočina a její klany; lovci, pastevci a traperi.$q$, 12),
($q$sage$q$, $q$Sage |cs| Učenec$q$, $q$You spent your years among books, at a university or in a lord's library, and you still have questions nobody can answer. |cs| Léta jsi strávil mezi knihami, na univerzitě nebo v pánově knihovně, a pořád máš otázky, na které nikdo nezná odpověď.$q$, $q$[{"options": [{"entries": [{"items": ["quarterstaff"], "quantity": 1}, {"items": ["small-knife"], "quantity": 1}, {"items": ["history-book"], "quantity": 1}, {"items": ["dead-colleague-letter"], "quantity": 1}, {"items": ["quill"], "quantity": 1}, {"items": ["ink"], "quantity": 1}, {"items": ["parchment"], "quantity": 5}, {"items": ["scholars-robe"], "quantity": 1}]}]}]$q$::jsonb, 50, 2, 2, $q$Universities and libraries; scholars and their patrons. |cs| Univerzity a knihovny; učenci a jejich mecenáši.$q$, 13),
($q$sailor$q$, $q$Sailor |cs| Námořník$q$, $q$You worked the decks of a cog or a river barge, hauling rope in storms and drinking in every port. |cs| Dřel jsi na palubě koggy nebo říčního člunu, tahal lana v bouři a pil v každém přístavu.$q$, $q$[{"options": [{"entries": [{"items": ["club", "dagger", "handaxe"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["leather-jerkin"], "quantity": 1}, {"items": ["mariners-compass"], "quantity": 1}, {"items": ["sounding-line"], "quantity": 1}, {"items": ["ruler"], "quantity": 1}, {"items": ["hemp-rope"], "quantity": 1}, {"items": ["lucky-charm"], "quantity": 1}, {"items": ["sailors-clothes"], "quantity": 1}]}]}]$q$::jsonb, 350, 2, 1, $q$Ports and ships; sailors, dockhands and smugglers. |cs| Přístavy a lodě; námořníci, přístavní dělníci a pašeráci.$q$, 14),
($q$scribe$q$, $q$Scribe |cs| Písař$q$, $q$You copied deeds, letters and ledgers in a chancery or a town hall. You've read things you were never meant to. |cs| Opisoval jsi listiny, dopisy a účetní knihy v kanceláři nebo na radnici. Četl jsi věci, které jsi číst neměl.$q$, $q$[{"options": [{"entries": [{"items": ["dagger", "quarterstaff"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["small-knife"], "quantity": 1}, {"items": ["quill"], "quantity": 1}, {"items": ["ink"], "quantity": 1}, {"items": ["parchment"], "quantity": 10}, {"items": ["sealing-wax"], "quantity": 1}, {"items": ["lamp"], "quantity": 1}, {"items": ["oil-flask"], "quantity": 3}, {"items": ["scholars-robe"], "quantity": 1}]}]}]$q$::jsonb, 600, 2, 1, $q$Town halls and chanceries; records and those who keep them. |cs| Radnice a kanceláře; záznamy a ti, kdo je vedou.$q$, 15),
($q$soldier$q$, $q$Soldier |cs| Voják$q$, $q$You marched in a lord's army or a mercenary company. You know how to stand in a line, and how to run from one. |cs| Pochodoval jsi v pánově vojsku nebo v žoldnéřské rotě. Víš, jak stát v šiku, i jak z něj utéct.$q$, $q$[{"options": [{"entries": [{"items": ["spear"], "quantity": 1}, {"items": ["shortbow"], "quantity": 1}, {"items": ["arrows"], "quantity": 1}, {"items": ["quiver"], "quantity": 1}]}, {"entries": [{"items": ["spear", "handaxe", "mace", "battleaxe", "flail", "warhammer", "halberd", "glaive", "maul", "greataxe", "longsword", "shortsword", "greatsword", "scimitar"], "quantity": 1}, {"items": ["spear", "handaxe", "mace", "battleaxe", "flail", "warhammer", "halberd", "glaive", "maul", "greataxe", "longsword", "shortsword", "greatsword", "scimitar"], "quantity": 1}]}, {"entries": [{"items": ["spear", "handaxe", "mace", "battleaxe", "flail", "warhammer", "halberd", "glaive", "maul", "greataxe", "longsword", "shortsword", "greatsword", "scimitar"], "quantity": 1}, {"items": ["shield", "heater-shield", "kite-shield"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["gambeson"], "quantity": 1}, {"items": ["kettle-hat"], "quantity": 1}, {"items": ["rank-insignia"], "quantity": 1}, {"items": ["enemy-trophy"], "quantity": 1}, {"items": ["splints"], "quantity": 1}, {"items": ["needle-and-thread"], "quantity": 1}, {"items": ["common-clothes"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["dice-set", "playing-cards"], "quantity": 1}]}]}]$q$::jsonb, 250, 4, 0, $q$War camps and garrisons; soldiers, veterans and quartermasters. |cs| Vojenské tábory a posádky; vojáci, veteráni a proviantní.$q$, 16),
($q$urchin$q$, $q$Urchin |cs| Uličník$q$, $q$You grew up on the streets, sleeping under bridges and stealing bread. You know every alley and every guard's habits. |cs| Vyrostl jsi na ulici, spal pod mosty a kradl chleba. Znáš každou uličku i zvyky každého strážného.$q$, $q$[{"options": [{"entries": [{"items": ["sling"], "quantity": 1}, {"items": ["sling-bullets"], "quantity": 1}]}, {"entries": [{"items": ["club"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["dagger"], "quantity": 1}, {"items": ["city-map"], "quantity": 1}, {"items": ["pet-mouse"], "quantity": 1}, {"items": ["parents-token"], "quantity": 1}, {"items": ["common-clothes"], "quantity": 1}]}]}]$q$::jsonb, 600, 1, 0, $q$Back streets and gutters; beggars and street children. |cs| Zapadlé uličky a stoky; žebráci a děti ulice.$q$, 17),
($q$wayfarer$q$, $q$Wayfarer |cs| Tulák$q$, $q$You never stayed anywhere long: odd jobs, cheap inns and a pack on your back. The road is the only home you know. |cs| Nikde jsi dlouho nezůstal: příležitostná práce, levné hospody a ranec na zádech. Cesta je jediný domov, který znáš.$q$, $q$[{"options": [{"entries": [{"items": ["dagger"], "quantity": 2}, {"items": ["file"], "quantity": 1}, {"items": ["lockpicks"], "quantity": 1}, {"items": ["small-mirror"], "quantity": 1}, {"items": ["scissors"], "quantity": 1}, {"items": ["pliers"], "quantity": 1}, {"items": ["bedroll"], "quantity": 1}, {"items": ["pouch"], "quantity": 2}, {"items": ["travellers-clothes"], "quantity": 1}]}]}, {"options": [{"entries": [{"items": ["dice-set", "playing-cards"], "quantity": 1}]}]}]$q$::jsonb, 250, 1, 1, $q$Roadside inns and hostels; vagrants, pedlars and pilgrims. |cs| Hospody u cest a noclehárny; tuláci, podomní obchodníci a poutníci.$q$, 18),
($q$monster-hunter$q$, $q$Monster hunter |cs| Lovec netvorů$q$, $q$You hunted things that hunt people: drowners in the millpond, a ghoul in the churchyard, whatever the village couldn't name. It paid badly, but the silver on your blade is yours. |cs| Lovil jsi to, co loví lidi: utopence v rybníku u mlýna, ghúla na hřbitově, cokoli, co vesnice neuměla pojmenovat. Platilo se špatně, ale stříbro na tvé čepeli je tvoje.$q$, $q$[{"options": [{"entries": [{"items": ["dagger", "spear", "handaxe", "mace", "battleaxe", "warhammer", "flail", "shortsword", "longsword"], "quantity": 1, "note": "Silvered"}]}]}, {"options": [{"entries": [{"items": ["hide-jerkin"], "quantity": 1}, {"items": ["torch"], "quantity": 3}, {"items": ["hemp-rope"], "quantity": 1}, {"items": ["enemy-trophy"], "quantity": 1}, {"items": ["bedroll"], "quantity": 1}, {"items": ["waterskin"], "quantity": 1}, {"items": ["common-clothes"], "quantity": 1}]}]}]$q$::jsonb, 30, 2, 0, $q$Haunted villages and the folk who pay to be rid of things; tales and rumours of the supernatural. |cs| Strašidelné vesnice a lidé, kteří platí, aby se něčeho zbavili; pověsti a zvěsti o nadpřirozenu.$q$, 19);
